mapper.select:
SELECT id,aggregate_id,operation,local_organization_id,local_before_json,local_after_json,operator_user_id,recorded_at,reason,verification_reference,source
FROM person_foundation_event WHERE aggregate_type='PERSON' AND aggregate_id=CAST(#{person} AS CHAR) AND local_organization_id=#{organization}
ORDER BY aggregate_version LIMIT #{limit} OFFSET #{offset}

